import java.util.*;

class Solution {
  public int depthSumInverse(List<NestedInteger> nestedList) {
    // weight = maxDepth - depth + 1 = (maxDepth + 1) * sum - sum(value * depth)
    long[] acc = new long[3]; // {sum of values, sum of value * depth, max depth}
    walk(nestedList, 1, acc);
    return (int) ((acc[2] + 1) * acc[0] - acc[1]);
  }

  private void walk(List<NestedInteger> list, int depth, long[] acc) {
    acc[2] = Math.max(acc[2], depth);
    for (NestedInteger ni : list) {
      if (ni.isInteger()) {
        acc[0] += ni.getInteger();
        acc[1] += (long) ni.getInteger() * depth;
      } else walk(ni.getList(), depth + 1, acc);
    }
  }
}
